@Override public boolean onNavigationItemSelected(@NonNull MenuItem item){
  final int action=item.getItemId();
  try {
    switch (action) {
      case R.id.action_delete:    onActionDiscard();
        break;
      case R.id.action_send:onActionCheck(false);
        break;
      default:onAction(action);
    }
  } catch (IllegalArgumentException | UnsupportedOperationException | RejectedExecutionException e) {
    e.printStackTrace();
  }
  return true;
}
